def parse(xml_or_file: Union[AnyStr, IO[str]], version: Optional[str]=None
    ) ->mod_gpx.GPX:
    from . import gpxxml as mod_gpxxml
    if hasattr(xml_or_file, 'read'):
        xml = xml_or_file.read()
    else:
        xml = xml_or_file
    parser = mod_gpxxml.GPXXMLParser(xml)
    return parser.parse(version)
